const input = $json.body ?? $json;
const description = String(input.description ?? '').trim();
if (description.length < 10) throw new Error('description must contain at least 10 characters');
const text = `${input.short_description ?? ''} ${description}`;
const rules = [
  ['Security','Security Operations',/ransomware|malware|phishing|compromis|suspicious login|data leak/i],
  ['Identity & Access','Microsoft 365 / Identity',/password|sign[ -]?in|login|mfa|authenticat|account lock|access denied|credential/i],
  ['Network','Network Connectivity',/vpn|wifi|wi-fi|network|dns|internet|latency|packet loss/i],
  ['Endpoint','Managed Endpoint',/laptop|desktop|blue screen|bsod|device|intune|disk|cpu/i],
  ['Application','Business Application',/application|app |website|portal|error 5\d\d|crash/i],
  ['Email & Collaboration','Microsoft 365',/outlook|email|mailbox|teams|sharepoint|onedrive/i]
];
const match = rules.find(([, , pattern]) => pattern.test(text));
const category = match?.[0] ?? 'General IT';
const service = match?.[1] ?? 'Service Desk';
const users = Math.max(1, Number(input.affected_users) || 1);
const critical = Boolean(input.business_critical);
const security = /ransomware|data leak|compromis|active attack/i.test(text);
const outage = /all users|company[- ]wide|site[- ]wide|complete outage|service down/i.test(text);
let priority = 'P3';
if (security || (critical && outage)) priority = 'P1';
else if (outage || users >= 25 || critical) priority = 'P2';
else if (/request|how do i|information/i.test(text)) priority = 'P4';
const confidence = match ? 0.82 : 0.55;
const actions = {
  'Security':['Preserve available evidence','Isolate affected assets when authorized','Escalate to the security response team'],
  'Identity & Access':["Verify the user's identity through the approved process",'Check account, license and authentication state','Review recent password or MFA changes and active sessions'],
  'Network':['Confirm scope and affected locations','Collect connection, DNS and VPN status','Compare with monitoring and known outages'],
  'Endpoint':['Record device and operating-system details','Check management and health status','Collect relevant error messages and logs'],
  'Application':['Confirm application, environment and exact error','Check service health and recent changes','Reproduce safely and capture timestamps'],
  'Email & Collaboration':['Check Microsoft 365 service health','Confirm account, license and client state','Compare web and desktop client behavior'],
  'General IT':['Confirm impact, scope and start time','Collect exact errors and recent changes','Check known issues before assignment']
};
const team = category === 'Security' ? 'Security Operations' : category === 'Identity & Access' ? 'IAM Support' : category === 'Network' ? 'Network Operations' : 'Service Desk / Application Owner';
return [{ json: { schema_version:'1.0', incident_id:String(input.incident_id ?? `DEMO-${Date.now()}`), short_description:String(input.short_description ?? description.slice(0,90)), category, service, priority, confidence, reasoning:`Rule-based baseline matched ${category}; priority reflects stated scope, criticality and security indicators.`, initial_actions:actions[category], escalation_team:team, human_review_required:priority === 'P1' || priority === 'P2' || confidence < 0.7, ai_status:'not_used', data_notice:'Sanitized demonstration data only; human validation required.' } }];
